 <script>
+const canvas=document.getElementById('arena'),ctx=canvas.getContext('2d');
+const $=id=>document.getElementById(id);const grades=['GRADO 4','GRADO 3','GRADO 2','GRADO 1','GRADO ESPECIAL'];
+const fighters={miwa:{name:'MIWA',full:'Kasumi Miwa',icon:'M',cost:0,skill:'DOMINIO SIMPLE',skillIcon:'◉',desc:'Corte rápido · defensa precisa',color:'#87a9f3',hp:100,damage:19},megumi:{name:'MEGUMI',full:'Megumi Fushiguro',icon:'影',cost:180,skill:'PERROS DIVINOS',skillIcon:'🐺',desc:'Invoca shikigami que persiguen',color:'#7a79a7',hp:115,damage:17},nobara:{name:'NOBARA',full:'Nobara Kugisaki',icon:'釘',cost:150,skill:'RESONANCIA',skillIcon:'✹',desc:'Clavos malditos a distancia',color:'#db826e',hp:95,damage:15},ino:{name:'TAKUMA INO',full:'Takuma Ino',icon:'👹',cost:210,skill:'BESTIA AUSPICIOSA',skillIcon:'☯',desc:'Golpe de bestia con máscara',color:'#89a889',hp:120,damage:22}};
+let coins=120,owned={miwa:true},hero='miwa',round=1,player={x:280,y:340,hp:100,max:100,face:1,attack:0,skillFx:0,invuln:0},enemy={x:690,y:340,hp:60,max:60,attack:0,hit:0},gameStarted=false,paused=false,finished=false,toastTimer=0,skillCooldown=0,dashCooldown=0,keys={},touchMove={},last=0,elapsed=0;
+function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=r.width*d;canvas.height=r.height*d;ctx.setTransform(canvas.width/960,0,0,canvas.height/480,0,0)}new ResizeObserver(resize).observe(canvas);resize();
+function enemyStats(){return [60,85,110,145,205][round-1]}function enemyName(){return ['LARVA MALDITA','ESPÍRITU ERRANTE','MALDICIÓN DEFORME','ESPÍRITU MALDITO','EL DEVORADOR'][round-1]}
+function showToast(t){const el=$('toast');el.textContent=t;el.classList.add('show');toastTimer=1.6}
+function updateHud(){const f=fighters[hero];$('heroName').textContent=f.name;$('heroPortrait').textContent=f.icon;$('heroHpText').textContent=Math.ceil(player.hp)+' / '+player.max;$('heroHealth').style.width=Math.max(0,player.hp/player.max*100)+'%';$('enemyName').textContent=enemyName();$('enemyHpText').textContent=Math.ceil(enemy.hp)+' / '+enemy.max;$('enemyHealth').style.width=Math.max(0,enemy.hp/enemy.max*100)+'%';$('roundNo').textContent=String(round).padStart(2,'0')+' / 05';$('waveTag').textContent=grades[round-1]+'　·　RONDA '+round;$('coins').textContent=coins;$('shopCoins').textContent=coins;$('skillLabel').textContent=f.skill;$('skillIcon').textContent=f.skillIcon;$('objective').textContent=round===5?'DERROTA AL GRADO ESPECIAL':'EXORCIZA LA MALDICIÓN';$('subObjective').textContent='Derrota al enemigo para ganar ✦';}
+function openShop(){paused=true;$('shop').classList.remove('hidden');renderShop()}function closeShop(){ $('shop').classList.add('hidden');if(!$('pause').classList.contains('hidden'))return;paused=false}
+function renderShop(){const roster=$('roster');roster.innerHTML='';for(const id of ['megumi','nobara','ino']){const f=fighters[id],has=owned[id],selected=hero===id,card=document.createElement('article');card.className='fighter-card';card.innerHTML=`<div class="avatar" style="color:${f.color}">${f.icon}</div><h3>${f.name}</h3><small>${f.desc}</small><button class="buy ${has?'owned':''}" ${!has&&coins<f.cost?'disabled':''}>${selected?'EN COMBATE':has?'ELEGIR':'✦ '+f.cost+' · RECLUTAR'}</button>`;card.querySelector('button').onclick=()=>{if(has){selectHero(id);renderShop()}else if(coins>=f.cost){coins-=f.cost;owned[id]=true;selectHero(id);showToast(f.name+' SE UNE A LA MISIÓN');renderShop()}};roster.appendChild(card)}}
+function selectHero(id){hero=id;const f=fighters[id];player.max=f.hp;player.hp=Math.min(player.hp+22,f.hp);updateHud()}
+$('openShop').onclick=openShop;$('closeShop').onclick=closeShop;$('startBtn').onclick=()=>{$('intro').classList.add('hidden');gameStarted=true;showToast('¡EXORCIZA LAS CINCO OLEADAS!')};$('pauseBtn').onclick=()=>{if(!gameStarted||finished)return;paused=true;$('pause').classList.remove('hidden')};$('resumeBtn').onclick=()=>{$('pause').classList.add('hidden');paused=false};$('pauseShop').onclick=()=>{$('pause').classList.add('hidden');openShop()};$('resultShop').onclick=()=>{$('result').classList.add('hidden');finished=false;gameStarted=true;openShop()};$('againBtn').onclick=()=>location.reload();$('attackBtn').addEventListener('pointerdown',e=>{e.preventDefault();attack()});$('skillBtn').addEventListener('pointerdown',e=>{e.preventDefault();skill()});$('dashBtn').addEventListener('pointerdown',e=>{e.preventDefault();dash()});
+function setMove(btn,on){btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.setPointerCapture(e.pointerId);touchMove[btn.dataset.move]=true});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>btn.addEventListener(ev,()=>touchMove[btn.dataset.move]=false))}document.querySelectorAll('.move-btn').forEach(b=>setMove(b,true));
+window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='j'||k==='z')attack();if(k==='k'||k==='x')skill();if(k===' ')dash();if(k==='escape'&&gameStarted&&!finished){paused=!paused;$('pause').classList.toggle('hidden',!paused)}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{keys={};touchMove={}});
+function attack(){if(!gameStarted||paused||finished||player.attack>0)return;player.attack=.27;player.face=enemy.x>=player.x?1:-1;const d=Math.hypot(enemy.x-player.x,enemy.y-player.y);if(d<142){enemy.hp=Math.max(0,enemy.hp-fighters[hero].damage);enemy.hit=.25;showToast(['¡CORTE!','¡IMPACTO!','¡MALDICIÓN!'][Math.floor(Math.random()*3)]);if(enemy.hp<=0)winRound()}}
+function skill(){if(!gameStarted||paused||finished||skillCooldown>0)return;skillCooldown=4.8;player.skillFx=.55;const id=hero,d=Math.hypot(enemy.x-player.x,enemy.y-player.y);if(id==='nobara'){enemy.hp=Math.max(0,enemy.hp-35);enemy.hit=.32;showToast('¡RESONANCIA! · ALCANCE TOTAL')}else if(id==='megumi'){enemy.hp=Math.max(0,enemy.hp-43);enemy.hit=.42;showToast('¡PERROS DIVINOS!')}else if(id==='ino'){enemy.hp=Math.max(0,enemy.hp-48);enemy.hit=.4;player.invuln=.5;showToast('¡BESTIA AUSPICIOSA!')}else{if(d<190){enemy.hp=Math.max(0,enemy.hp-45);enemy.hit=.4}player.invuln=.65;showToast('¡DOMINIO SIMPLE! · CONTRAGOLPE')}if(enemy.hp<=0)winRound()}
+function dash(){if(!gameStarted||paused||finished||dashCooldown>0)return;dashCooldown=1.6;player.invuln=.38;const dx=(keys.d||keys.arrowright||touchMove.right?1:keys.a||keys.arrowleft||touchMove.left?-1:player.face),dy=(keys.s||keys.arrowdown||touchMove.down?1:keys.w||keys.arrowup||touchMove.up?-1:0);player.x=Math.max(60,Math.min(900,player.x+dx*90));player.y=Math.max(245,Math.min(410,player.y+dy*50));player.face=dx<0?-1:1}
+function winRound(){if(finished)return;coins+=[45,60,75,100,180][round-1];updateHud();if(round===5){finished=true;gameStarted=false;$('resultEyebrow').textContent='GRADO ESPECIAL EXORCIZADO';$('resultTitle').textContent='MISIÓN COMPLETADA';$('resultText').textContent='La estación vuelve a estar en silencio. Has exorcizado las cinco oleadas y ganado '+coins+' fragmentos. El mundo jujutsu está un poco más seguro.';$('result').classList.remove('hidden');return}round++;enemy.max=enemyStats();enemy.hp=enemy.max;enemy.x=700;enemy.y=320+Math.random()*65;enemy.attack=0;player.hp=Math.min(player.max,player.hp+22);updateHud();showToast('OLEADA '+(round-1)+' SUPERADA　+✦ · SIGUIENTE: '+grades[round-1]);}
+function lose(){finished=true;gameStarted=false;$('resultEyebrow').textContent='MISIÓN INTERRUMPIDA';$('resultTitle').textContent='HAS CAÍDO';$('resultText').textContent='Las maldiciones te han superado en la oleada '+round+'. Recluta un aliado en la tienda y vuelve a intentarlo.';$('result').classList.remove('hidden')}
+updateHud();

