function rr(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function drawBackground(t){const g=ctx.createLinearGradient(0,0,0,480);g.addColorStop(0,'#26262c');g.addColorStop(.58,'#343037');g.addColorStop(1,'#18181d');ctx.fillStyle=g;ctx.fillRect(0,0,960,480);
// distant city and stained glass station
ctx.fillStyle='#202126';for(let i=0;i<12;i++){const x=i*93-20,h=90+(i*37%100);ctx.fillRect(x,120-h*.35,70,h);ctx.fillStyle='#484046';for(let wy=0;wy<3;wy++)for(let wx=0;wx<3;wx++){ctx.fillStyle=(i+wx+wy)%4===0?'#d18b6644':'#c6a56724';ctx.fillRect(x+12+wx*17,132-h*.35+wy*22,7,10)}ctx.fillStyle='#202126'}
// station canopy
ctx.fillStyle='#101115';ctx.beginPath();ctx.moveTo(0,126);ctx.lineTo(960,110);ctx.lineTo(960,152);ctx.lineTo(0,168);ctx.fill();ctx.strokeStyle='#716970';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,166);ctx.lineTo(960,150);ctx.stroke();
// old train
const train=ctx.createLinearGradient(0,175,0,320);train.addColorStop(0,'#565057');train.addColorStop(.12,'#c1b6a2');train.addColorStop(.18,'#803e41');train.addColorStop(.23,'#d0c3ad');train.addColorStop(1,'#48454a');ctx.fillStyle=train;ctx.beginPath();ctx.moveTo(-20,172);ctx.lineTo(980,157);ctx.lineTo(980,309);ctx.quadraticCurveTo(970,330,940,330);ctx.lineTo(18,330);ctx.quadraticCurveTo(-10,327,-20,300);ctx.fill();ctx.strokeStyle='#e2d3bb44';ctx.lineWidth=2;ctx.stroke();
for(let i=0;i<7;i++){const x=28+i*140;rr(x,194,112,89,6,'#282a30','#c2b9ae66');const win=ctx.createLinearGradient(0,198,0,280);win.addColorStop(0,'#293842');win.addColorStop(1,'#657075');ctx.fillStyle=win;ctx.fillRect(x+5,199,102,77);ctx.fillStyle='#e9cf9950';ctx.fillRect(x+12,206,25,5);ctx.fillStyle='#111216';ctx.fillRect(x+52,194,5,89);ctx.fillStyle='#e2c48233';for(let j=0;j<3;j++)ctx.fillRect(x+14+j*27,284,15,3)}
// platform and tiles
ctx.fillStyle='#827b77';ctx.beginPath();ctx.moveTo(0,326);ctx.lineTo(960,320);ctx.lineTo(960,366);ctx.lineTo(0,369);ctx.fill();ctx.fillStyle='#d3c4ad';ctx.fillRect(0,326,960,4);ctx.fillStyle='#595456';ctx.fillRect(0,348,960,4);ctx.strokeStyle='#b8a99355';for(let i=0;i<14;i++){ctx.beginPath();ctx.moveTo(i*85,330);ctx.lineTo(i*85-20,365);ctx.stroke()}
const floor=ctx.createLinearGradient(0,365,0,480);floor.addColorStop(0,'#393237');floor.addColorStop(1,'#17171b');ctx.fillStyle=floor;ctx.fillRect(0,365,960,115);ctx.strokeStyle='#bcae9c24';ctx.lineWidth=1;for(let i=0;i<12;i++){ctx.beginPath();ctx.moveTo(i*100-40,480);ctx.lineTo(460+(i-5)*22,365);ctx.stroke()}ctx.beginPath();ctx.moveTo(0,424);ctx.lineTo(960,419);ctx.stroke();
// cursed residue and floating embers
for(let i=0;i<14;i++){const x=(i*173+80)%960,y=120+((i*71)%260);const pulse=.45+.5*Math.sin(t*2+i);ctx.fillStyle=i%3===0?`rgba(239,71,68,${pulse*.32})`:`rgba(187,103,116,${pulse*.2})`;ctx.beginPath();ctx.arc(x+Math.sin(t+i)*4,y,2+(i%3),0,Math.PI*2);ctx.fill()}ctx.fillStyle='#11121655';ctx.fillRect(0,368,960,112)}
function drawHero(x,y,t,isEnemy=false){ctx.save();ctx.translate(x,y);if(isEnemy){drawCurse(t)}else drawFighter(t);ctx.restore()}
function drawFighter(t){const f=fighters[hero],swing=player.attack>0,move=(keys.a||keys.d||keys.arrowleft||keys.arrowright||touchMove.left||touchMove.right)?Math.sin(t*14)*3:Math.sin(t*3)*1.5;ctx.save();ctx.translate(0,move);ctx.scale(player.face,1);
// shadow
ctx.fillStyle='#07080b88';ctx.beginPath();ctx.ellipse(0,0,35,8,0,0,Math.PI*2);ctx.fill();
// legs
ctx.fillStyle='#191a20';ctx.fillRect(-18,-37,14,34);ctx.fillRect(4,-37,14,34);ctx.fillStyle='#34343a';ctx.fillRect(-20,-8,18,8);ctx.fillRect(3,-8,19,8);
// jacket / torso
ctx.fillStyle=f.color;ctx.beginPath();ctx.moveTo(-21,-79);ctx.lineTo(17,-79);ctx.lineTo(24,-39);ctx.lineTo(-24,-39);ctx.closePath();ctx.fill();ctx.fillStyle='#202127';ctx.fillRect(-8,-78,9,38);ctx.fillStyle='#e2dcd4';ctx.beginPath();ctx.moveTo(-5,-77);ctx.lineTo(0,-65);ctx.lineTo(5,-77);ctx.fill();
// collar + head
ctx.fillStyle='#212127';ctx.fillRect(-14,-91,28,16);ctx.fillStyle='#e6c6ad';ctx.beginPath();ctx.ellipse(0,-96,13,16,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=hero==='miwa'?'#24324a':hero==='nobara'?'#9c6443':'#20202b';ctx.beginPath();ctx.moveTo(-14,-99);ctx.quadraticCurveTo(-11,-120,4,-113);ctx.quadraticCurveTo(14,-112,14,-98);ctx.lineTo(8,-102);ctx.lineTo(-5,-104);ctx.lineTo(-13,-96);ctx.fill();ctx.fillStyle='#29242a';ctx.fillRect(5,-97,5,2);
// arms
ctx.strokeStyle='#e6c6ad';ctx.lineWidth=8;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-18,-72);ctx.lineTo(-28,-53);ctx.moveTo(17,-72);ctx.lineTo(swing?43:25,swing?-66:-51);ctx.stroke();ctx.fillStyle=f.color;ctx.fillRect(-33,-62,12,8);ctx.fillRect(swing?38:20,-60,12,8);
// signature sword held forward
ctx.save();ctx.translate(42,swing?-72:-51);ctx.rotate(swing?-1.35:-.65);ctx.strokeStyle='#d8d6d1';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,-57);ctx.stroke();ctx.strokeStyle='#edcf83';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-7,-3);ctx.lineTo(7,-3);ctx.stroke();ctx.restore();
if(player.attack>0){ctx.strokeStyle='#ecf2f5cc';ctx.lineWidth=5;ctx.beginPath();ctx.arc(18,-61,47,-1.2,.7);ctx.stroke();ctx.strokeStyle='#b7d5ff88';ctx.lineWidth=12;ctx.beginPath();ctx.arc(18,-61,49,-1.1,.4);ctx.stroke()}
if(player.invuln>0){ctx.strokeStyle='#b8dafa88';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,-58,43,59,0,0,Math.PI*2);ctx.stroke()}
if(player.skillFx>0){ctx.strokeStyle=f.color+'aa';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,-55,55+(1-player.skillFx)*100,0,Math.PI*2);ctx.stroke()}
ctx.restore()}
function drawCurse(t){const pulse=Math.sin(t*5)*3;ctx.fillStyle='#08090bb0';ctx.beginPath();ctx.ellipse(0,0,43,9,0,0,Math.PI*2);ctx.fill();if(enemy.hit>0){ctx.globalAlpha=.5+Math.sin(t*45)*.5}
// tendrils
ctx.strokeStyle='#581e35';ctx.lineWidth=10;ctx.lineCap='round';for(let i=0;i<4;i++){const side=i<2?-1:1,yy=-40-(i%2)*18;ctx.beginPath();ctx.moveTo(side*13,yy);ctx.quadraticCurveTo(side*(43+Math.sin(t*4+i)*10),yy-18,side*(36+Math.sin(t*3+i)*8),yy-49);ctx.stroke();ctx.strokeStyle='#9d3e51';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(side*13,yy);ctx.quadraticCurveTo(side*(43+Math.sin(t*4+i)*10),yy-18,side*(36+Math.sin(t*3+i)*8),yy-49);ctx.stroke();ctx.strokeStyle='#581e35';ctx.lineWidth=10}
const body=ctx.createRadialGradient(-12,-79,4,0,-58,52);body.addColorStop(0,'#bb5b67');body.addColorStop(.6,'#783146');body.addColorStop(1,'#35192a');ctx.fillStyle=body;ctx.beginPath();ctx.ellipse(0,-51-pulse,34,48,Math.sin(t*3)*.06,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b54b5a';ctx.beginPath();ctx.ellipse(0,-102-pulse,27,24,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#24151e';ctx.beginPath();ctx.ellipse(0,-97-pulse,18,12,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f6d58a';ctx.beginPath();ctx.ellipse(-9,-102-pulse,4,6,0,0,Math.PI*2);ctx.ellipse(9,-102-pulse,4,6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#190f15';ctx.beginPath();ctx.moveTo(-7,-84-pulse);ctx.lineTo(0,-76-pulse);ctx.lineTo(7,-84-pulse);ctx.fill();ctx.strokeStyle='#d4919b';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-23,-53);ctx.lineTo(-45,-39+Math.sin(t*6)*4);ctx.moveTo(23,-59);ctx.lineTo(44,-72+Math.cos(t*5)*5);ctx.stroke();ctx.globalAlpha=1}

