r;gap:10px;min-width:0}.portrait{width:36px;height:36px;border-radius:50%;background:#27272c;border:1px solid #ffffff22;display:grid;place-items:center;color:var(--lime);font:800 15px 'Barlow Condensed';flex:none}.fighter-meta{width:min(310px,33vw)}.fighter-label{font:700 12px 'Barlow Condensed';letter-spacing:1.1px;display:flex;justify-content:space-between;margin-bottom:5px}.fighter-label small{font:600 9px 'DM Sans';letter-spacing:.5px;color:#a2a0a4}.healthbar{height:7px;border-radius:9px;background:#ffffff15;overflow:hidden}.healthfill{height:100%;width:100%;background:linear-gradient(90deg,#bd393b,#f2645f);transition:width .2s}.enemy-status{flex-direction:row-reverse;text-align:right}.enemy-status .portrait{color:#ff7373;border-color:#f0524f55}.enemy-status .healthfill{margin-left:auto;background:linear-gradient(90deg,#fa554d,#af2531)}.round-label{background:#ffffff0b;border:1px solid var(--line);padding:8px 13px;text-align:center;border-radius:3px;white-space:nowrap}.round-label small{display:block;font:700 8px 'DM Sans';color:#999;letter-spacing:1.4px}.round-label strong{font:800 12px 'Barlow Condensed';letter-spacing:1px}.arena-wrap{position:relative;flex:1;min-height:0;border:1px solid #ffffff17;background:#17171b;overflow:hidden}.arena-wrap:after{content:'';position:absolute;inset:0;pointer-events:none;border:1px solid #ffffff05;box-shadow:inset 0 0 80px #08080bb0}.arena{width:100%;height:100%;display:block}.arena-tag{position:absolute;z-index:2;top:15px;left:16px;color:#d4d0cb;font:700 9px 'DM Sans';letter-spacing:1.5px;display:flex;align-items:center;gap:8px;text-transform:uppercase}.live-dot{width:6px;height:6px;background:var(--red);border-radius:100%;box-shadow:0 0 10px var(--red)}.wave-tag{position:absolute;z-index:2;top:13px;right:15px;background:#0d0e10a8;border:1px solid #ffffff20;padding:7px 10px;color:#ddd;font:700 9px 'DM Sans';letter-spacing:1px}.toast{position:absolute;z-index:3;top:18%;left:50%;transform:translate(-50%,-10px);background:#121315de;border:1px solid #ffffff2a;padding:9px 17px;font:800 13px 'Barlow Condensed';letter-spacing:1.4px;opacity:0;transition:.25s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.bottom{height:116px;display:flex;align-items:center;justify-content:space-between;gap:18px;flex:none}.objective{align-self:stretch;display:flex;flex-direction:column;justify-content:center;min-width:190px}.eyebrow{font:700 9px 'DM Sans';letter-spacing:1.6px;color:#9b999a}.objective strong{font:800 20px 'Barlow Condensed';letter-spacing:.7px;margin:3px 0}.objective p{font-size:10px;color:#aaa;margin:0}.controls{display:flex;align-items:center;gap:9px}.control-hint{font-size:9px;color:#8f8d91;line-height:1.6;margin-right:8px}.key{display:inline-grid;place-items:center;min-width:19px;height:19px;border:1px solid #ffffff30;border-radius:3px;background:#ffffff0a;color:#eee;font-size:9px;font-weight:800;margin:1px}.action-btn{position:relative;width:65px;height:65px;border-radius:50%;background:#212226;border:1px solid #ffffff26;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;box-shadow:0 4px 12px #0007;user-select:none;touch-action:none}.action-btn .ico{font-size:19px;line-height:21px}.action-btn b{font:800 8px 'DM Sans';letter-spacing:.8px}.action-btn.attack{background:#a93638;border-color:#fa69668c}.action-btn.skill{background:#34322e;border-color:#e4c47970}.action-btn.dash{width:53px;height:53px;background:#20252a}.action-btn:active,.action-btn.pressed{transform:scale(.94);filter:brightness(1.35)}.cooldown{position:absolute;inset:0;border-radius:50%;background:#08090ab8;display:none;align-items:center;justify-content:center;font:800 15px 'Barlow Condensed'}.action-btn.cooling .cooldown{display:flex}.mobile-pad{display:none;gap:7px}.move-btn{width:48px;height:48px;border-radius:12px;background:#ffffff0c;border:1px solid #ffffff24;color:#e8e4de;font-size:18px;touch-action:none;user-select:none}.overlay{position:absolute;inset:0;z-index:10;background:#090a0bd9;backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:center;padding:18px}.overlay.hidden{display:none}.modal{width:min(590px,100%);max-height:100%;overflow:auto;background:#17181b;border:1px solid #ffffff21;padding:29px;box-shadow:0 25px 100px #000b}.modal-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.modal h1,.modal h2{font:900 36px/.95 'Barlow Condensed';letter-spacing:.5px;margin:5px 0 10px}.modal h1 em{font-style:normal;color:var(--red)}.modal p{color:#a7a5a7;font-size:12px;line-height:1.55}.close{background:#ffffff10;border:1px solid #ffffff20;border-radius:4px;padding:7px 10px;color:#bbb}.roster{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.fighter-card{background:#202125;border:1px solid #ffffff18;padding:13px 12px;min-height:132px;position:relative}.fighter-card .avatar{font:900 26px 'Barlow Condensed';color:var(--lime);margin-bottom:5px}.fighter-card h3{margin:0;font:800 16px 'Barlow Condensed';letter-spacing:.7px}.fighter-card small{display:block;color:#a5a2a1;font-size:9px;min-height:25px;margin-top:3px}.fighter-card .buy{width:100%;margin-top:8px;padding:8px 5px;background:#d8ff75;color:#15170f;border-radius:3px;font-size:10px;font-weight:900}.fighter-card .buy.owned{background:#33363a;color:#d8ff75}.fighter-card .buy:disabled{opacity:.55}.primary{background:var(--red);padding:12px 19px;font-weight:900;font-size:11px;letter-spacing:1.2px;border-radius:3px}.secondary{background:#ffffff0c;border:1px solid #ffffff22;padding:11px 16px;font-weight:800;font-size:10px;letter-spacing:1px;border-radius:3px}.start-actions{display:flex;align-items:center;gap:10px;margin-top:19px;flex-wrap:wrap}.intro-card{max-width:470px}.intro-stats{display:flex;gap:18px;padding:13px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-top:16px}.intro-stats div{font-size:10px;color:#aaa}.intro-stats strong{display:block;font:800 18px 'Barlow Condensed';color:#eee}.rank-list{display:flex;gap:6px;flex-wrap:wrap;margin-top:13px}.rank-chip{padding:5px 8px;border:1px solid #ffffff17;background:#ffffff08;color:#c5c2c1;font-size:9px;font-weight:700;letter-spacing:.4px}.rank-chip.special{border-color:#e75f5660;color:#ff8177}.gameover .modal{text-align:center}.gameover h2{font-size:42px}.tip{position:absolute;bottom:9px;left:50%;transform:translateX(-50%);white-space:nowrap;font-size:8px;color:#777;letter-spacing:.4px}
 @media(max-width:700px){.game{height:100dvh;min-height:0;width:100%;padding:env(safe-area-inset-top) 13px env(safe-area-inset-bottom);gap:7px;border:0}.topbar{height:43px}.brand-mark{width:30px;height:30px;font-size:15px}.brand{gap:9px}.brand-title{font-size:18px}.brand-title small{font-size:7px}.top-right{gap:6px}.currency{padding:7px 9px;font-size:11px}.store-btn{height:34px;padding:0 11px;font-size:9px}.pause-btn{height:34px}.status-row{height:42px;gap:5px}.fighter-status{gap:6px}.portrait{width:29px;height:29px;font-size:12px}.fighter-meta{width:min(35vw,180px)}.fighter-label{font-size:10px;margin-bottom:4px}.fighter-label small{font-size:8px}.healthbar{height:6px}.round-label{padding:5px 7px}.round-label small{font-size:7px}.round-label strong{font-size:10px}.arena-wrap{min-height:200px}.arena-tag{top:10px;left:10px;font-size:8px}.wave-tag{top:8px;right:8px;font-size:8px;padding:6px 7px}.bottom{height:125px;gap:6px;align-items:center;justify-content:space-between}.objective{min-width:0;max-width:115px}.objective strong{font-size:17px}.objective p{font-size:8px}.eyebrow{font-size:7px}.controls{gap:7px}.control-hint{display:none}.action-btn{width:59px;height:59px}.action-btn .ico{font-size:18px}.action-btn.dash{width:48px;height:48px}.mobile-pad{display:flex;flex-direction:column;gap:4px}.pad-row{display:flex;gap:4px}.move-btn{width:39px;height:36px;border-radius:8px;font-size:16px}.tip{display:none}.modal{padding:22px 18px}.modal h1,.modal h2{font-size:32px}.roster{gap:6px}.fighter-card{padding:10px 8px;min-height:125px}.fighter-card .avatar{font-size:23px}.fighter-card h3{font-size:14px}.fighter-card small{font-size:8px}.fighter-card .buy{font-size:9px;padding:8px 3px}.intro-stats{gap:12px}.overlay{padding:12px}}

